import json,hashlib,pathlib
p=pathlib.Path('.')
s=p.joinpath('global_prompt.md').read_text()
def img(id,path,prompt):return dict(id=id,path=path,prompt_path=prompt,status='pending',size_px=None,reference_images=[],sha256=None)
m=dict(schema_version=1,source=dict(path='global_prompt.md',sha256=hashlib.sha256(s.encode()).hexdigest()),status='planned',settings=dict(verification=True,timing=True,style='realistic photography',frame_aspect_ratio='16:9',frame_size_px=[1536,864],max_attempts_per_image=5),assumptions=['Room has pale walls, light oak flooring, a black-framed window on the far wall, and no other furnishings.','Table is fixed: 180 cm along x, 90 cm along y. Initial near side is y=-45 cm; far side y=45 cm; right short side x=90 cm. Window is beyond far side. A=(45,15), B=(65,30), C=(0,0) cm on tabletop. Positions are not printed on images.','Man has short black hair, clean-shaven face, plain grey long-sleeve shirt, dark charcoal trousers and black shoes.','Wooden cup is handleless warm brown wood; porcelain cup is plain white with one handle and dark tea; tissue pack is soft blue unbranded plastic with a white dispensing opening.'],assets=[],shots=[],changes=[],reviews=[],sequence_review=dict(decision='pending',notes='',checks=[]),blockers=[])
data=[('room','background','Daylight room, rectangular wooden table, floor-to-ceiling window overlooking lawn','a rectangular wooden table, and a daylight room with a floor-to-ceiling window overlooking a lawn.'),('man','character','Ordinary adult East Asian man, short black hair, grey shirt, dark trousers, black shoes','an ordinary adult East Asian man in a grey shirt and dark trousers'),('tissue_pack','object','One soft blue plastic-wrapped tissue pack','A soft blue plastic-wrapped tissue pack rests at A'),('wooden_cup','object','One empty handleless wooden cup with visible interior','an empty wooden cup rests at B, with its interior visible.'),('porcelain_cup','object','One white porcelain handled cup containing dark tea','a white porcelain cup containing dark tea appears instantaneously at C.')]
for id,kind,desc,quote in data:
 folder={'background':'backgrounds','character':'characters','object':'objects'}[kind]; base=f'assets/{folder}/{id}'
 anchors=[dict(id='room.'+n,description=d) for n,d in [('table','Fixed rectangular oak table'),('window','Far-wall floor-to-ceiling window and lawn'),('A','Table coordinate (45,15) cm'),('B','Table coordinate (65,30) cm'),('C','Table center (0,0) cm')]] if kind=='background' else []
 im=img(id+'.image',base+('/image.png' if kind=='background' else '/front.png'),base+'/prompt.txt')
 m['assets'].append(dict(id=id,kind=kind,description=desc,source_quotes=[quote],invariants=[desc,'Exactly one physical instance'],anchors=anchors,background_mode='scene' if kind=='background' else 'opaque',transparency_reason=None,image=im))
 prompt=('Generate one realistic photograph. '+desc+'. '+ ('Landscape 1536x864. Slightly elevated view facing across near long side of the fixed table toward window. Entire bare tabletop visible. Pale walls, light oak floor, black window frames, green lawn outdoors. No people, tissue packs, cups, chairs, text or watermark.' if kind=='background' else 'Neutral opaque light grey backdrop. '+('Portrait, front-facing neutral standing pose, head to toe including both feet, empty hands; no props.' if kind=='character' else 'Square product photograph, one isolated instance. Front means the main broad face of the pack or the side of the cup, with a slightly elevated angle showing opening and contents. No other objects.')+' No text, logos or watermark.'))
 pathlib.Path(base).mkdir(parents=True,exist_ok=True); pathlib.Path(im['prompt_path']).write_text(prompt)
for n in range(1,4):
 cameras={1:'Slightly elevated near-side view toward window, drifting gently toward near-right corner; keep tabletop A and B unobstructed.',2:'Distinct slightly elevated view from beyond right short side toward table center and left wall, gently tracking toward far-right corner; keep B and C unobstructed.',3:'Distinct elevated view from near-left side toward man on opposite long side with window and lawn behind him; gentle push in keeps B and C clearly visible.'}
 action={1:'Man walks counterclockwise from near long side to right short side without touching anything. At shot time 3 seconds the entire tissue pack disappears instantaneously; wooden cup stays empty at B.',2:'Man continues counterclockwise from right short side to opposite long side without touching anything. At shot time 3 seconds a white porcelain cup containing dark tea appears instantaneously at C.',3:'During first second man turns head toward window then back. At shot time 2 seconds the cups exchange positions instantaneously with hands away: empty wooden cup to C, tea-filled porcelain cup to B. Only afterward he picks up porcelain cup from B and drinks, ending with it at his lips.'}[n]
 shot=dict(id=f'shot_{n}',duration_seconds=5,background_id='room',prompt_path=f'shot_{n}/prompt.txt',action=action,camera_motion=cameras[n],invariants=['Natural motion, no text or watermark','One continuous shot, no internal cuts','No sliding, morphing, fading, handling or occlusion to cause sudden changes','Table and room remain fixed; cup materials and contents follow cup identity'],frames={})
 for edge in ['first','last']:
  tissue=n==1 and edge=='first'; porcelain=n>2 or (n==2 and edge=='last'); held=n==3 and edge=='last'
  pos={1:('near long side','right short side'),2:('right short side','opposite long side within reach of B and C'),3:('opposite long side within reach of B and C','opposite long side')}[n][edge=='last']
  entities=[dict(asset_id='man',presence='in_scene',visibility='visible',state=f'Standing at {pos}; '+('holding porcelain cup at lips' if held else 'watching table, hands away from objects')),dict(asset_id='tissue_pack',presence='in_scene' if tissue else 'elsewhere',visibility='visible' if tissue else 'out_of_frame',state='At A' if tissue else 'Absent'),dict(asset_id='wooden_cup',presence='in_scene',visibility='visible',state='Empty at '+('C' if held else 'B')),dict(asset_id='porcelain_cup',presence='in_scene' if porcelain else 'elsewhere',visibility='visible' if porcelain else 'out_of_frame',state=('At lips after pickup from B; drinking dark tea' if held else 'At C containing dark tea') if porcelain else 'Absent')]
  rel=[dict(subject='man',predicate='beside',object='room.table',space='world',description=pos)]
  for ob,loc in [('wooden_cup','C' if held else 'B')]+([('tissue_pack','A')] if tissue else [])+([('porcelain_cup','C')] if porcelain and not held else []):
   rel.append(dict(subject=ob,predicate='on',object='room.'+loc,space='world',description=f'{ob} supported by tabletop at fixed {loc}'))
  if held:rel.append(dict(subject='man',predicate='holding',object='porcelain_cup',space='world',description='Right hand holds porcelain cup at lips after pickup from B'))
  base=f'shot_{n}/generation_reference_frames';pathlib.Path(base).mkdir(parents=True,exist_ok=True)
  shot['frames'][edge]=dict(image=img(f'shot_{n}.{edge}',base+f'/{edge}.png',base+f'/{edge}.prompt.txt'),camera=cameras[n]+(' Opening camera position.' if edge=='first' else ' Ending camera position after gentle motion.'),entities=entities,relations=rel)
 text=f'Shot {n}, {(n-1)*5}–{n*5} seconds: Use the first and last supplied images as the opening and ending anchors. One continuous five-second shot. {action} {cameras[n]} A is the initial near-side view’s upper-right tabletop region; B is slightly farther right and farther away than A; C is the center. These positions stay fixed in world space. Counterclockwise viewed from above means near long side to right short side to opposite long side. Keep relevant tabletop areas unobstructed during the instantaneous event, with hands away. Preserve cup materials and contents. No sliding, morphing, fading, occlusion tricks or internal cuts. Natural human movement; no text or watermark.'
 pathlib.Path(shot['prompt_path']).write_text(text)
 m['shots'].append(shot)
 eventquotes=['At exactly 3 seconds into this shot, the entire tissue pack disappears instantaneously from the unobstructed tabletop.','At exactly 3 seconds into this shot (8 seconds overall), a white porcelain cup containing dark tea appears instantaneously at C.','At exactly 2 seconds into this shot (12 seconds overall), the two cups instantaneously exchange positions: the empty wooden cup moves to C, and the tea-filled porcelain cup moves to B.']
 m['changes'].append(dict(**{'from':f'shot_{n}.first','to':f'shot_{n}.last'},entity_ids=[['tissue_pack'],['porcelain_cup'],['wooden_cup','porcelain_cup']][n-1],kind='intentional_discontinuity',description=eventquotes[n-1],source_quote=eventquotes[n-1]))
 m['changes'].append(dict(**{'from':f'shot_{n}.first','to':f'shot_{n}.last'},entity_ids=['man'],kind='action',description=action,source_quote=s.split(f'Shot {n},')[1].split('\n\n')[0]))
 m['changes'].append(dict(**{'from':f'shot_{n}.first','to':f'shot_{n}.last'},entity_ids=['room'],kind='camera',description=cameras[n],source_quote='Use three distinct, slightly elevated camera views with gentle continuous camera movement within each shot.'))
 if n>1:m['changes'].append(dict(**{'from':f'shot_{n-1}.last','to':f'shot_{n}.first'},entity_ids=['room','man','tissue_pack','wooden_cup','porcelain_cup'],kind='camera',description='Cut to distinct camera viewpoint; all world states preserved.',source_quote="Match each shot's opening object state to the preceding shot's ending state; introduce no changes at cuts."))
pathlib.Path('pipeline.json').write_text(json.dumps(m,indent=2)+'\n')
